import sys

def main():
    input_data = sys.stdin.read().split()
    if not input_data:
        return

    iterator = iter(input_data)
    try:
        R = int(next(iterator))
        C = int(next(iterator))
    except StopIteration:
        return

    matrix = []
    for _ in range(R):
        row = []
        for _ in range(C):
            row.append(int(next(iterator)))
        matrix.append(tuple(row))

    seen = set()
    result = []

    for i in range(R):
        row_tuple = matrix[i]
        if row_tuple in seen:
            result.append(i)
        else:
            seen.add(row_tuple)

    print(*(result))

if __name__ == "__main__":
    main()
